import{_ as t,o as e,c as o,ag as l}from"./chunks/framework.CAXxHpAX.js";const s=JSON.parse('{"title":"任脉","description":"","frontmatter":{},"headers":[],"relativePath":"50-概念资料/dict-任脉.md","filePath":"50-概念资料/dict-任脉.md","lastUpdated":1778155802000}'),r={name:"50-概念资料/dict-任脉.md"};function i(c,a,d,u,h,n){return e(),o("div",null,[...a[0]||(a[0]=[l('<h1 id="任脉" tabindex="-1">任脉 <a class="header-anchor" href="#任脉" aria-label="Permalink to &quot;任脉&quot;">​</a></h1><blockquote><p>传统：丹道/中医</p></blockquote><h2 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to &quot;定义&quot;">​</a></h2><p>任脉是人体奇经八脉之一，位于身体前正中线，起于会阴，沿腹部、胸部上行至下颌。任脉主&quot;阴&quot;，与全身阴经相连。</p><h2 id="了空居士原话" tabindex="-1">了空居士原话 <a class="header-anchor" href="#了空居士原话" aria-label="Permalink to &quot;了空居士原话&quot;">​</a></h2><blockquote><p>&quot;任脉在前，属阴。任脉通了，下面的气才能上来。&quot;</p></blockquote><blockquote><p>&quot;神守黄房——黄房乃乾之下、坤之上。这个位置其实就是中丹田，也在任脉上。&quot;</p></blockquote><blockquote><p>&quot;练功时主要守中丹田（膻中一带），不要去守着任脉走。气满自通，不用意念引导。&quot;</p></blockquote><h2 id="了空居士的观点" tabindex="-1">了空居士的观点 <a class="header-anchor" href="#了空居士的观点" aria-label="Permalink to &quot;了空居士的观点&quot;">​</a></h2><p>了空居士从不鼓励&quot;运气通关&quot;，而是强调气满自通。他推荐观照的区域是中丹田（膻中一带），这是任脉上的重要位置。</p><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/50-概念资料/dict-督脉">督脉</a> — 任脉的对应</li><li><a href="/50-概念资料/dict-小周天">小周天</a> — 任督循环形成小周天</li><li><a href="/50-概念资料/dict-丹田">丹田</a> — 上中下三丹田都在任脉上</li></ul><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/10-核心模型/model-性命双修">性命双修</a></li></ul>',14)])])}const p=t(r,[["render",i]]);export{s as __pageData,p as default};
